import 'dart:convert';
import 'dart:io';

/// Generates `lib/languages/language_<abbr>.dart` from TeX hyphenation
/// pattern files located in `tool/tex/hyph-<abbr>.tex`.
///
/// The generated file contains the patterns and exceptions in their
/// original TeX notation as `const` lists - compact and readable.
///
/// Usage:
/// ```shell
/// dart run tool/tex2data.dart ru
/// dart run tool/tex2data.dart ru en_us
/// ```
///
/// Pattern sources: https://tug.org/tex-hyphen/
void main(List<String> args) {
  if (args.isEmpty) {
    stderr.writeln('Usage: dart run tool/tex2data.dart <abbr> [<abbr> ...]');
    exit(64);
  }

  for (final abbr in args) {
    _generate(abbr);
  }
}

void _generate(String abbr) {
  final texFile = File('tool/tex/hyph-$abbr.tex');
  if (!texFile.existsSync()) {
    stderr.writeln('Not found: ${texFile.path}');
    exit(66);
  }

  final patterns = <String>{};
  final exceptions = <String>{};

  bool isNextPattern = false;
  bool isNextException = false;

  for (var line in texFile.readAsLinesSync()) {
    line = line.trim();
    if (line.isEmpty || line.startsWith('%')) continue;

    if (line.startsWith('}')) {
      isNextPattern = false;
      isNextException = false;
    } else if (!isNextPattern &&
        !isNextException &&
        line.startsWith('\\patterns')) {
      isNextPattern = true;
    } else if (!isNextPattern &&
        !isNextException &&
        line.startsWith('\\hyphenation')) {
      isNextException = true;
    } else if (isNextPattern) {
      patterns.add(line);
    } else if (isNextException) {
      exceptions.add(line);
    }
  }

  final sortedPatterns = patterns.toList()..sort();
  final sortedExceptions = exceptions.toList()..sort();

  _verifyAgainstJson(abbr, sortedPatterns, sortedExceptions);

  final out = StringBuffer()
    ..writeln('// GENERATED FILE - do not edit manually.')
    ..writeln(
        '// Generated by `tool/tex2data.dart` from `tool/tex/hyph-$abbr.tex`.')
    ..writeln('// TeX hyphenation patterns: https://tug.org/tex-hyphen/')
    ..writeln("import 'package:hyphenatorx/languages/languageconfig.dart';")
    ..writeln()
    ..writeln('/// Hyphenation configuration for `${abbr}`.')
    ..writeln('class ${_className(abbr)} implements LanguageConfig {')
    ..writeln('  const ${_className(abbr)}();')
    ..writeln()
    ..writeln('  /// Patterns in TeX notation.')
    ..writeln(
        '  /// A digit marks the inter-letter level between its surrounding letters.')
    ..writeln('  @override')
    ..writeln('  final List<String> patterns = const <String>[')
    ..write(_formatList(sortedPatterns))
    ..writeln('  ];')
    ..writeln()
    ..writeln('  /// Exceptions in TeX notation.')
    ..writeln('  /// A `-` marks an allowed break point.')
    ..writeln('  @override')
    ..writeln('  final List<String> exceptions = const <String>[')
    ..write(_formatList(sortedExceptions))
    ..writeln('  ];')
    ..writeln('}');

  final outFile = File('lib/languages/language_$abbr.dart');
  outFile.writeAsStringSync(out.toString());

  stdout.writeln(
      'Generated ${outFile.path}: ${sortedPatterns.length} patterns, ${sortedExceptions.length} exceptions.');
}

/// Formats the entries as rows of [perRow] comma separated string literals.
String _formatList(List<String> entries, {int perRow = 6}) {
  final buffer = StringBuffer();
  for (var i = 0; i < entries.length; i += perRow) {
    final row = entries
        .skip(i)
        .take(perRow)
        .map((e) => "'${e.replaceAll(r'\', r'\\').replaceAll("'", r"\'")}'")
        .join(', ');
    buffer.writeln('    $row,');
  }
  return buffer.toString();
}

/// The generated file is the source of truth, but if a legacy JSON asset
/// exists, it is used to verify the parsed patterns and exceptions.
void _verifyAgainstJson(
    String abbr, List<String> patterns, List<String> exceptions) {
  final jsonFile = File('assets/language_$abbr.json');
  if (!jsonFile.existsSync()) return;

  final data = json.decode(jsonFile.readAsStringSync()) as Map<String, dynamic>;

  final jsonPatterns = <String, List<int>>{};
  for (final entry in (data['pattern'] as List)) {
    jsonPatterns[(entry as Map)['result'] as String] =
        List<int>.from(entry['levels'] as List);
  }

  final jsonExceptions = <String, List<int>>{};
  for (final entry
      in ((data['exception'] ?? <String, dynamic>{}) as Map).entries) {
    jsonExceptions[entry.key as String] = List<int>.from(entry.value as List);
  }

  var errors = 0;

  final parsedPatterns = <String, List<int>>{};
  for (final source in patterns) {
    final parsed = _parsePattern(source);
    final previous = parsedPatterns[parsed.$1];
    if (previous != null && previous.toString() != parsed.$2.toString()) {
      stderr.writeln('Pattern conflict: ${parsed.$1}');
      errors++;
    }
    parsedPatterns[parsed.$1] = parsed.$2;
  }

  for (final entry in jsonPatterns.entries) {
    final parsed = parsedPatterns[entry.key];
    if (parsed == null) {
      stderr.writeln('Missing in TeX: pattern ${entry.key}');
      errors++;
    } else if (parsed.toString() != entry.value.toString()) {
      stderr.writeln('Levels differ: ${entry.key}');
      errors++;
    }
  }

  final parsedExceptions = <String, List<int>>{};
  for (final source in exceptions) {
    final parsed = _parseException(source);
    parsedExceptions[parsed.$1] = parsed.$2;
  }

  for (final entry in jsonExceptions.entries) {
    final parsed = parsedExceptions[entry.key];
    if (parsed == null) {
      stderr.writeln('Missing in TeX: exception ${entry.key}');
      errors++;
    } else if (_trimTrailingZeros(parsed).toString() !=
        _trimTrailingZeros(entry.value).toString()) {
      stderr.writeln('Mask differs: ${entry.key}');
      errors++;
    }
  }

  if (errors > 0) {
    stderr.writeln('$errors verification errors for `$abbr`. Aborting.');
    exit(65);
  }

  stdout.writeln('Verified against ${jsonFile.path}: OK.');
}

/// Mirrors the runtime parser in CalculationHelper.
(String, List<int>) _parsePattern(String source) {
  final levels = <int>[];
  final result = StringBuffer();

  var expectLevel = true;
  for (final rune in source.runes) {
    final digit = rune - 0x30;
    if (digit >= 0 && digit <= 9) {
      levels.add(digit);
      expectLevel = false;
    } else {
      if (expectLevel) levels.add(0);
      result.writeCharCode(rune);
      expectLevel = true;
    }
  }
  if (expectLevel) levels.add(0);

  return (result.toString(), levels);
}

/// Mirrors the runtime parser in CalculationHelper.
///
/// A `-` marks a break point BEFORE the letter following it, so the mask
/// contains one entry per letter (the break) plus one trailing entry.
(String, List<int>) _parseException(String source) {
  final mask = <int>[];
  final key = StringBuffer();

  var breakBeforeNext = false;
  for (final rune in source.runes) {
    if (rune == 0x2D) {
      breakBeforeNext = true;
    } else {
      key.writeCharCode(rune);
      mask.add(breakBeforeNext ? 1 : 0);
      breakBeforeNext = false;
    }
  }
  mask.add(0);

  return (key.toString(), mask);
}

/// `en_us` becomes `LanguageEnUs`.
String _className(String abbr) =>
    'Language' +
    abbr
        .split('_')
        .map((part) =>
            part.isEmpty ? part : part[0].toUpperCase() + part.substring(1))
        .join();

/// Legacy JSON masks and freshly parsed masks may differ in trailing zeros,
/// which never affect the hyphenation result.
List<int> _trimTrailingZeros(List<int> mask) {
  var end = mask.length;
  while (end > 0 && mask[end - 1] == 0) {
    end--;
  }
  return mask.sublist(0, end);
}
